/*
 * prog41_series_sum – reproduced from the original binary.
 *
 * The program expects exactly two integer command‑line arguments:
 *
 *   prog41_series_sum MODE LIMIT
 *
 *   MODE  – selects the series to evaluate.
 *           1 :  Σ_{i=1}^{LIMIT} 1/(i*i)          (Basel problem partial sum)
 *           3 :  Σ_{k=0}^{LIMIT} 1/k!            (approximation of e)
 *
 *   LIMIT – non‑negative integer, at most 100 000.
 *
 * Behaviour (matching the original binary):
 *
 *   * If fewer than two arguments are supplied → prints "NO_INPUT".
 *   * If either argument is not a valid integer → prints "BAD_INPUT".
 *   * If LIMIT is negative → prints "BAD_INPUT".
 *   * If LIMIT > 100000 → prints "OUT_OF_RANGE".
 *   * If MODE is neither 1 nor 3 → prints "BAD_MODE".
 *   * Otherwise computes the selected series and prints the result
 *     with six digits after the decimal point.
 *
 * All messages are terminated with a newline, exactly as the original
 * program does (via puts/printf).
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* ---------- argument count check ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- parse first argument (MODE) ---------- */
    char *endptr1;
    errno = 0;
    long mode = strtol(argv[1], &endptr1, 10);
    if (errno != 0 || *endptr1 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- parse second argument (LIMIT) ---------- */
    char *endptr2;
    errno = 0;
    long limit = strtol(argv[2], &endptr2, 10);
    if (errno != 0 || *endptr2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (limit < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (limit > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- select mode ---------- */
    if (mode == 1) {
        /* Σ 1/(i*i) for i = 1 .. limit */
        double sum = 0.0;
        for (long i = 1; i <= limit; ++i) {
            sum += 1.0 / ((double)i * (double)i);
        }
        printf("%.6f\n", sum);
        return 0;
    }

    if (mode == 3) {
        /* Σ 1/k! for k = 0 .. limit  (approximation of e) */
        double term = 1.0;   /* 1/0! */
        double sum  = term;  /* start with k = 0 term */

        for (long k = 1; k <= limit; ++k) {
            term /= (double)k;   /* term = 1/k! */
            sum  += term;
        }
        printf("%.6f\n", sum);
        return 0;
    }

    /* any other mode is unsupported */
    puts("BAD_MODE");
    return 0;
}
